//! @profile testnet -- NOT the mainnet projection.
//!
//! Generated by `python3 config/gen.py --profile testnet` from
//! `config/params.json` overlaid with `config/params.testnet.json`. The mainnet
//! projection is `poc/solana/programs/solbeam/src/params.rs`; the program and
//! the test suite do not read this file, so deploying it is a deliberate copy.
//!
//! Overridden rows, and why they differ:
//!   lc.cluster_id
//!       First concrete value for a row that was `open` and had none. The
//!       identifier is the BSV testnet genesis hash -- measured from the node's
//!       chainparams, not invented -- so a testnet deposit is bound to the
//!       testnet chain rather than to no cluster. It moves from `open` to
//!       `designed` + `measured` because a value now exists while the binding is
//!       still out of the program.
//!   lc.pow_limit_bits
//!       Concretised to the single value BSV testnet actually uses. The mainnet
//!       row carries the `mainnet / regtest` pair because the code covers both
//!       chains; testnet's limit is mainnet's, so this is measured rather than
//!       chosen. Recorded here with the min-difficulty gap, which is a real
//!       obstacle for a testnet deployment and must not be left implicit.
//!   v.maturity_blocks
//!       Shorter than 144 because a 24-hour maturity makes a test cycle a day
//!       long. 6 keeps the mechanism exercised and the confirmations + maturity
//!       <= window constraint satisfied. This is a deliberate weakening of the
//!       reorg window for testing only; the value is a stored Config field, so
//!       mainnet is untouched.
//!   v.reorg_margin
//!       Recomputed, not independently chosen: window (192) - maturity (6) = 186.
//!       Leaving the mainnet 48 would make this derived row's own definition
//!       ('window - maturity') false for the profile.
//!   pi.min_peg_in
//!       Lowered from 1 BSV because testnet coins are free: the mainnet floor
//!       prices out no griefing there and only makes a deposit test harder to
//!       fund. 0.01 BSV (1,000,000 base units) equals po.d_min, so a deposit can
//!       never be below the smallest redeemable amount.
//!   po.deadline
//!       Shorter than 216,000 for the same reason as maturity: a test cycle
//!       should not be a day long. 3,600 slots is about 24 minutes at the 400 ms
//!       target slot -- minutes, not hours, but long enough for a member to
//!       actually pay on testnet. The field is timelock-mutable if a test needs
//!       it shorter.

//! The SOLBEAM parameter sheet, as Rust constants.
//!
//! @generated by `config/gen.py` from `config/params.json` -- do not
//! edit by hand.  `config/params.json` is the single source; the human
//! tables in `docs/parameters.csv` and `docs/06-parameters.md`, this file
//! and `tests/params.json` are all projections of it.  The generator
//! computes every projection before it writes any of them, and refuses if
//! the JSON and a projection disagree, so the document, the CSV and the
//! code cannot drift.
//!
//! Regenerate with `python3 config/gen.py`.
//!
//! `difficulty.rs` includes this file by relative `#[path]` as well, so
//! the cw-144 rule's spacing, clamps and lookback come from the same
//! generated values without giving that module a Solana dependency (it
//! is `#[path]`-included by the plain `cargo test` vectors crate).
#![allow(dead_code)]

// -- lc --

/// `lc.window_hours` -- Window length (hours) -- `32 dec`.
///
/// How much BSV history the client keeps. Sets the deposit deadline
pub const WINDOW_HOURS: u64 = 32;

/// `lc.seconds_per_block` -- Target block spacing -- `600 mea`.
///
/// BSV's ten-minute target
pub const SECONDS_PER_BLOCK: u64 = 600;

/// `lc.window` -- Window length (records) -- `192 der`.
///
/// window_hours × 3600 / seconds_per_block. Bounded above by the account cap
pub const WINDOW: usize = (WINDOW_HOURS * 3600 / SECONDS_PER_BLOCK) as usize;

/// `lc.record_size` -- Bytes per header record -- `52 der`.
///
/// 32 hash + 16 chainwork + 4 time. Not configurable
pub const HEADER_RECORD_SIZE: usize = 52;

/// `lc.lookback` -- DAA lookback (records) -- `147 der`.
///
/// 144 + 3 for the median-of-three. Measured: 146 reproduces 0/324 headers, 147 reproduces 324/324
pub const LOOKBACK_RECORDS: u64 = 147;

/// `lc.lookback` -- DAA lookback (records) -- `147 der`.
///
/// 144 + 3 for the median-of-three. Measured: 146 reproduces 0/324 headers, 147 reproduces 324/324
pub const SEED_RECORDS: usize = 147;

/// `lc.floor` -- Confirmation depth -- `12 blocks built`.
///
/// MIN_CONFIRMATIONS, fixed in code, not a runtime parameter
pub const MIN_CONFIRMATIONS: u64 = 12;

/// `lc.max_staleness_slots` -- Freshness bound -- `54,000 slots (~6 h) built`.
///
/// How recent the last accepted header must be before release. A multiple of BSV block time — ~1,500 Solana slots per block. Implemented (StaleClient), untested on a local validator
pub const MAX_STALENESS_SLOTS: u64 = 54_000;

/// `lc.max_fork_batch` -- Headers per fork tx -- `12 mea`.
///
/// Set by the 1,232-byte transaction limit
pub const MAX_FORK_BATCH: usize = 12;

/// `lc.max_account_create` -- Solana account cap -- `10,240 bytes mea`.
///
/// A Solana limit, not a choice
pub const MAX_ACCOUNT_CREATE: usize = 10_240;

/// `lc.daa_clamp_low` -- Lower clamp -- `72 × 600 s mea`.
///
/// Multiplies seconds_per_block, not the averaging window
pub const DAA_CLAMP_LOW_MULTIPLIER: i64 = 72;

/// `lc.daa_clamp_high` -- Upper clamp -- `288 × 600 s mea`.
///
/// As above
pub const DAA_CLAMP_HIGH_MULTIPLIER: i64 = 288;

// -- v --

/// `v.maturity_blocks` -- Maturity -- `6 blocks`.
///
/// TESTNET ONLY: 6 blocks, not 144. A deliberate reduction in the protective window, so a test cycle is minutes of on-demand testnet mining rather than about 24 hours at BSV's 600 s target spacing. Six blocks is about an hour of chain time at the target; testnet blocks are generated on demand, which is what makes the cycle short. The reduction weakens reorg protection by exactly as much as it shortens the wait. Constraint: confirmations + maturity <= window, so 12 + 6 <= 192.
pub const DEFAULT_MATURITY_BLOCKS: u64 = 6;

// -- gov --

/// `gov.authority_timelock` -- Authority timelock -- `32 slots built`.
///
/// TIMELOCK_SLOTS, a PoC value. Applied to propose_authority_change / execute_authority_change / cancel_authority_change. Must be long enough to exit
pub const TIMELOCK_SLOTS: u64 = 32;

// -- m --

/// `m.token_decimals` -- solBSV decimals -- `8 mea`.
///
/// —
pub const TOKEN_DECIMALS: u8 = 8;

// -- fee --

/// `fee.redeem_bp` -- Peg-out fee (gross) -- `30 bp dec`.
///
/// As above
pub const REDEEM_FEE_BP: u64 = 30;

// -- po --

/// `po.payout_confirmations` -- Payout depth -- `6 BSV blocks built`.
///
/// BSV confirmations before a payout is provable. C_payout
pub const PAYOUT_CONFIRMATIONS: u64 = 6;

/// `po.challenge_window` -- Challenge window -- `144 BSV blocks built`.
///
/// W. Confirmations a payout needs before settling
pub const CHALLENGE_WINDOW: u64 = 144;

/// `po.deadline` -- Redemption deadline -- `3,600 slots built`.
///
/// How long a member has to pay before the holder may cancel. TESTNET ONLY: 3,600 slots, not 216,000. At Solana's 400 ms target slot that is about 24 minutes instead of about a day, so a redemption test is not a day long; it is long enough that a member can actually pay on testnet. In Solana slots, because a height deadline would never expire if the header feed stalled. cancel_redeem is refused while a claim is live, which closes the pay-and-refund race structurally rather than by the deadline's length.
pub const REDEEM_DEADLINE_SLOTS: u64 = 3_600;

/// `po.cancel_grace` -- Cancellation grace -- `0 built`.
///
/// Cancellation is immediate on expiry. A grace period would only delay the exit
pub const CANCEL_GRACE_SLOTS: u64 = 0;

/// `po.d_min` -- Minimum redemption -- `1,000,000 base units (0.01 BSV) built`.
///
/// Minimum redemption, so a claim's proof is worth the transaction fees to settle
pub const REDEEM_D_MIN: u64 = 1_000_000;

/// `po.max_pending` -- Concurrent redemption cap -- `64 built`.
///
/// Cap on concurrent pending redemptions, so the escrow cannot be used to make the program's per-instruction work unbounded
pub const MAX_PENDING_REDEMPTIONS: u64 = 64;

// -- pi --

/// `pi.min_peg_in` -- Minimum deposit -- `1,000,000 base units (0.01 BSV) dec`.
///
/// The floor verify_deposit enforces on a deposit output, in the base units the claim's amount is in. TESTNET ONLY: 0.01 BSV (1,000,000 base units), not 1 BSV. Testnet coins are free, so the 1 BSV mainnet floor prices out nothing there and only makes a deposit test harder to run; 0.01 BSV still exceeds dust and still exercises the floor. MIN_PEG_IN = 1,000,000 in the profile's params.rs. It equals po.d_min, the minimum redemption already in the sheet, so the deposit floor cannot sit above the smallest redeemable amount.
pub const MIN_PEG_IN: u64 = 1_000_000;

// -- fed --

/// `fed.script` -- Reserve deposit script -- `2-of-2 OP_CHECKMULTISIG dec, shape accepted in code built`.
///
/// OP_2 <gateway threshold key> <greycore key> OP_2 OP_CHECKMULTISIG. Both keys must sign; the Greycore polices every reserve spend. The committed code accepts this shape: is_reserve_multisig, MAX_SCRIPT_LEN = 71, DepositScript::SPACE = 84. The keys/quorum behind it are not built
pub const MAX_SCRIPT_LEN: usize = 71;
